describe('Notification Message Rendered - On-Screen Feedback', () => {
  beforeEach(() => {
    cy.visit('/notification_message_rendered');
  });

  it('should display notification with success message when action is triggered', () => {
    // Intercept the API call to simulate action
    cy.intercept('POST', '/api/trigger-notification').as('triggerNotification');

    // Click the 'Click here' link to trigger action
    cy.get('[data-testid="click-link"]').click();

    // Wait for the API call to complete
    cy.wait('@triggerNotification');

    // Verify notification flash element is visible
    cy.get('[data-testid="flash"]').should('be.visible');

    // Verify notification contains success message
    cy.get('[data-testid="flash"]').should('contain', 'Action successful');

    // Verify close icon is present
    cy.get('[data-testid="flash"]').should('contain', '.close');

    // Verify close icon is clickable
    cy.get('[data-testid="flash"]').should('be.visible');
    cy.get('[data-testid="flash"]').click();

    // Verify flash element is no longer visible
    cy.get('[data-testid="flash"]').should('not.exist');
  });

  it('should display notification with error message when action fails', () => {
    // Intercept the API call to simulate failure
    cy.intercept('POST', '/api/trigger-notification', {
      statusCode: 500,
      body: { error: 'Internal server error' }
    }).as('triggerNotificationError');

    // Click the 'Click here' link to trigger action
    cy.get('[data-testid="click-link"]').click();

    // Wait for the API call to complete
    cy.wait('@triggerNotificationError');

    // Verify notification flash element is visible
    cy.get('[data-testid="flash"]').should('be.visible');

    // Verify notification contains error message
    cy.get('[data-testid="flash"]').should('contain', 'Action unsuccessful');

    // Verify close icon is present
    cy.get('[data-testid="flash"]').should('contain', '.close');

    // Verify close icon is clickable
    cy.get('[data-testid="flash"]').should('be.visible');
    cy.get('[data-testid="flash"]').click();

    // Verify flash element is no longer visible
    cy.get('[data-testid="flash"]').should('not.exist');
  });
});
